INSERT INTO articulos (
  id,
  autor_id,
  categoria_id,
  titulo,
  slug,
  contenido,
  extracto,
  imagen_destacada,
  estado,
  etiquetas,
  metadata
) VALUES (
  '953f10a6-f9d4-4760-8414-2192d4ba8d48',
  COALESCE((SELECT id FROM perfiles WHERE rol_id = 1 LIMIT 1), (SELECT id FROM perfiles LIMIT 1)),
  NULL,
  'Capturar la bandera',
  'capturar-la-bandera',
  '<p>El juego Capturar la bandera es una actividad enfocada en el refuerzo de habilidades físicas y promover la elaboración de estrategias mediante el trabajo en equipo.</p><hr><h3>Definición y Objetivo</h3><p>La idea principal del juego es apoderarse de la bandera del equipo rival y llevarla hasta su propia base sin ser tocado por ningún defensor del equipo contrario.</p><hr><h3>Desarrollo del Juego</h3><ol><li><strong>Delimitación del Campo:</strong> El espacio de juego se divide en dos lados iguales, uno para cada equipo. Se puede identificar al atacante o al defensor de acuerdo a qué lado del campo se encuentre (si está en campo propio es defensor, si está en campo rival es atacante).</li><li><strong>Posición de los Jugadores:</strong> Cuando los que atacan están agachados no se pueden mover; para poder moverse deben estar de pie y los defensores deben estar a un mínimo de 3 pasos de distancia de ellos.</li><li><strong>Reglas de Ataque y Eliminación:</strong> Los atacantes sólo pueden capturar la bandera y evitar que los toquen, pero no pueden tocar a los rivales para eliminarlos. Si eliminan a un atacante, este debe volver a su campo y esperar 30 segundos para volver a salir.</li><li><strong>Transporte de la Bandera:</strong> Si un atacante toma la bandera rival, este puede ser tocado durante cualquier punto del camino hacia su base, y si lo tocan debe entregar la bandera al equipo rival.</li><li><strong>Victoria:</strong> El juego termina cuando uno de los que ataca lleva la bandera del otro equipo a su campo sin que nadie lo toque.</li></ol>',
  'El juego Capturar la bandera es una actividad enfocada en el refuerzo de habilidades físicas y promover la elaboración de estrategias mediante el trabajo en equipo.',
  'https://raw.githubusercontent.com/claudiomateluna/nua_mana/gh-pages/uploads/Actividad_CapturaLaBandera.png',
  'publicado',
  ARRAY['Refuerzo de habilidades físicas', 'trabajo en equipo', 'juegos de estrategia'],
  '{"areas": ["corporalidad", "sociabilidad"], "lugares": ["Campo Abierto", "Exterior"], "cantidad": "08 participantes", "duracion": "30 minutos", "unidades": ["compañía", "tropa", "avanzada"], "objetivos": ["Desfogue de Energías", "Promover la elaboración de estrategias", "Refuerzo de habilidades físicas", "Trabajo en equipo"], "materiales": ["Pañolin"], "variaciones": "", "recomendaciones": "", "justificacion_areas": "Fomenta la coordinación física y la resistencia cardiovascular mediante desafíos corporales dinámicos. Incentiva el cumplimiento de reglas, el trabajo cooperativo y el respeto de la seguridad grupal.", "imagen_destacada_url": "https://raw.githubusercontent.com/claudiomateluna/nua_mana/gh-pages/uploads/Actividad_CapturaLaBandera.png", "objetivos_educativos": [{"id": "705b686a-8374-467a-b871-f6470f0d58ae", "area": "Corporalidad", "texto": "Me doy cuenta de los cambios que se están produciendo en mi cuerpo.", "unidad": "Compañía", "como_se_cumple": "Desafiando mis habilidades físicas y motrices con esfuerzo y perseverancia al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "57887da4-c70e-45bc-bdfb-f79db513a89c", "area": "Corporalidad", "texto": "Sé qué hacer frente a una enfermedad o accidente.", "unidad": "Compañía", "como_se_cumple": "Integrando mis convicciones de fe y los valores scouts en mi vida cotidiana al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "8cae916f-5e67-4697-b3cd-c59b5c7d1439", "area": "Corporalidad", "texto": "Trato de evitar situaciones que puedan dañar mi salud y la de mis compañeros.", "unidad": "Tropa", "como_se_cumple": "Trabajando codo a codo con mi patrulla, apoyando a quienes más lo necesitan en la actividad al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "68add558-4b03-4105-b00d-e7f2ead6ac23", "area": "Corporalidad", "texto": "Sé qué hacer frente a una enfermedad o accidente.", "unidad": "Tropa", "como_se_cumple": "Integrando mis convicciones de fe y los valores scouts en mi vida cotidiana al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "05f42879-f5f5-40c4-bed6-c577bf61340a", "area": "Corporalidad", "texto": "Cuido mi salud y mantengo hábitos que la protegen.", "unidad": "Avanzada", "como_se_cumple": "Perfeccionando mis destrezas físicas y adoptando hábitos de entrenamiento y autocuidado al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Compañía", "como_se_cumple": "Respetando los acuerdos y normas de convivencia de mi patrulla para jugar seguro al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Compañía", "como_se_cumple": "Valorando y respetando las normas colectivas como base para el crecimiento del grupo al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Tropa", "como_se_cumple": "Respetando los acuerdos y normas de convivencia de mi patrulla para jugar seguro al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Tropa", "como_se_cumple": "Valorando y respetando las normas colectivas como base para el crecimiento del grupo al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}, {"id": "f1496221-0da5-4775-b3ba-29e65603cfee", "area": "Sociabilidad", "texto": "Acepto las normas de los diferentes ambientes en que actúo, sin renunciar a mi derecho de tratar de cambiarlas cuando no me parecen correctas.", "unidad": "Avanzada", "como_se_cumple": "Respetando las normas de convivencia grupales y proponiendo mejoras de manera democrática al trazar estrategias de invasión y sigilo para robar la bandera del equipo contrario y traerla a la base propia."}]}'::jsonb
);

